// Input Validation and Default Setting
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

// Validate required LinkedIn URL
if (!requestData.linkedin_company_url) {
  throw new Error('linkedin_company_url is required');
}

// Validate URL format
const linkedinUrlPattern = /linkedin\.com\/company\//i;
if (!linkedinUrlPattern.test(requestData.linkedin_company_url)) {
  throw new Error('Invalid LinkedIn company URL format');
}

// Set defaults
const config = {
  linkedin_company_url: requestData.linkedin_company_url,
  job_title_filters: requestData.job_title_filters || [
    "recruiter", "talent acquisition", "hr manager", "human resources",
    "people operations", "hiring manager", "talent partner"
  ],
  min_quality_score: requestData.min_quality_score || 60,
  batch_size: requestData.batch_size || 5,
  hot_threshold: requestData.hot_threshold || 80,
  warm_threshold: requestData.warm_threshold || 60,
  request_id: `hr-disco-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
  start_time: new Date().toISOString()
};

return [{
  json: config
}];

// Parse LinkedIn Company ID from URL
const inputData = $input.first().json;
const linkedinUrl = inputData.linkedin_company_url;

// Extract company slug/ID from URL
// Formats supported:
// - https://www.linkedin.com/company/company-name/
// - https://linkedin.com/company/12345/
const regex = /linkedin\.com\/company\/([^\/\?]+)/i;
const match = linkedinUrl.match(regex);

if (!match || !match[1]) {
  throw new Error('Could not extract company ID from LinkedIn URL');
}

const companyId = match[1];

return [{
  json: {
    ...inputData,
    company_id: companyId,
    company_slug: companyId
  }
}];

// Filter employees by HR-related roles
const inputData = $input.first().json;
const config = $node["Validate Input"].json;

// HR keywords for role detection
const hrKeywords = [
  "recruiter", "recruiting", "talent acquisition", "hr manager",
  "human resources", "people operations", "talent partner",
  "hiring manager", "staffing", "headhunter", "sourcer",
  "people & culture", "employee relations", "hr business partner",
  "talent management", "workforce planning", "hr director",
  "chief people officer", "vp of people", "head of talent"
];

// Seniority keywords
const seniorityLevels = {
  executive: ["vp", "vice president", "chief", "cpo", "head of", "director"],
  senior: ["senior", "sr", "lead", "principal"],
  mid: ["manager", "business partner"],
  junior: ["specialist", "coordinator", "associate", "recruiter"]
};

// Function to detect HR role
function isHRRole(title) {
  if (!title) return false;
  const lowerTitle = title.toLowerCase();
  return hrKeywords.some(keyword => lowerTitle.includes(keyword));
}

// Function to detect seniority
function detectSeniority(title) {
  if (!title) return "unknown";
  const lowerTitle = title.toLowerCase();

  for (const [level, keywords] of Object.entries(seniorityLevels)) {
    if (keywords.some(keyword => lowerTitle.includes(keyword))) {
      return level;
    }
  }
  return "entry";
}

// Function to calculate priority
function calculatePriority(title, seniority) {
  let priority = 0;

  // Seniority bonus
  const seniorityBonus = {
    executive: 50,
    senior: 30,
    mid: 20,
    junior: 10,
    entry: 5
  };
  priority += seniorityBonus[seniority] || 0;

  // High-value title keywords
  const highValueKeywords = ["director", "vp", "head of", "talent acquisition"];
  if (highValueKeywords.some(kw => title.toLowerCase().includes(kw))) {
    priority += 20;
  }

  return priority;
}

// Process employees
const employees = inputData.employees || [];
const filteredEmployees = employees
  .filter(emp => {
    const title = emp.title || emp.job_title || "";
    return isHRRole(title);
  })
  .map(emp => {
    const title = emp.title || emp.job_title || "";
    const seniority = detectSeniority(title);
    const priority = calculatePriority(title, seniority);

    return {
      ...emp,
      is_hr: true,
      seniority: seniority,
      priority: priority,
      hr_relevance_score: priority
    };
  })
  .sort((a, b) => b.priority - a.priority); // Sort by priority descending

return filteredEmployees.map(emp => ({ json: emp }));

// Extract contact hints from Proxycurl profile
const profile = $input.first().json;

try {
  // Extract basic info
  const firstName = profile.first_name || "";
  const lastName = profile.last_name || "";
  const fullName = profile.full_name || `${firstName} ${lastName}`.trim();

  // Extract company domain
  let companyDomain = "";
  if (profile.experiences && profile.experiences.length > 0) {
    const currentJob = profile.experiences[0];
    companyDomain = currentJob.company_linkedin_profile_url
      ? currentJob.company_linkedin_profile_url.split('/company/')[1]?.split('/')[0]
      : "";
  }

  // Extract from company field if available
  if (!companyDomain && profile.occupation) {
    const company = profile.occupation.split(' at ')[1];
    if (company) {
      // Try to convert company name to domain (basic heuristic)
      companyDomain = company.toLowerCase()
        .replace(/[^a-z0-9]/g, '')
        .replace(/inc|corp|llc|ltd|limited/g, '');
    }
  }

  // Extract profile metadata
  const linkedinUrl = profile.public_identifier
    ? `https://www.linkedin.com/in/${profile.public_identifier}`
    : profile.profile_url || "";

  const title = profile.occupation || profile.headline || "";
  const city = profile.city || "";
  const country = profile.country_full_name || profile.country || "";

  // Calculate profile freshness
  const lastUpdated = profile.last_updated || null;
  let daysSinceUpdate = null;
  if (lastUpdated) {
    const updateDate = new Date(lastUpdated);
    const now = new Date();
    daysSinceUpdate = Math.floor((now - updateDate) / (1000 * 60 * 60 * 24));
  }

  // Get company size from current experience
  let companySize = null;
  if (profile.experiences && profile.experiences[0]) {
    companySize = profile.experiences[0].company_size || null;
  }

  return [{
    json: {
      ...profile,
      first_name: firstName,
      last_name: lastName,
      full_name: fullName,
      company_domain: companyDomain,
      linkedin_url: linkedinUrl,
      title: title,
      city: city,
      country: country,
      days_since_update: daysSinceUpdate,
      company_size: companySize,
      seniority: profile.seniority || $json.seniority || "unknown",
      hr_relevance_score: $json.hr_relevance_score || 0
    }
  }];
} catch (error) {
  console.error('Error extracting contact hints:', error.message);
  return [{
    json: {
      ...profile,
      error: error.message,
      first_name: "",
      last_name: "",
      company_domain: "",
      linkedin_url: ""
    }
  }];
}

// Generate common email patterns
const data = $input.first().json;
const firstName = data.first_name || "";
const lastName = data.last_name || "";
const domain = data.company_domain || "";

if (!firstName || !lastName || !domain) {
  return [{
    json: {
      ...data,
      generated_emails: [],
      email_generation_failed: true
    }
  }];
}

const f = firstName.toLowerCase();
const l = lastName.toLowerCase();
const fInitial = f.charAt(0);
const lInitial = l.charAt(0);

// Ensure domain doesn't have protocol or path
const cleanDomain = domain.replace(/^https?:\/\//, '').split('/')[0];

// Common email patterns
const patterns = [
  `${f}.${l}@${cleanDomain}`,           // john.doe@company.com
  `${f}${l}@${cleanDomain}`,            // johndoe@company.com
  `${fInitial}${l}@${cleanDomain}`,     // jdoe@company.com
  `${f}@${cleanDomain}`,                // john@company.com
  `${f}_${l}@${cleanDomain}`,           // john_doe@company.com
  `${l}.${f}@${cleanDomain}`,           // doe.john@company.com
  `${fInitial}.${l}@${cleanDomain}`     // j.doe@company.com
];

// Remove duplicates
const uniquePatterns = [...new Set(patterns)];

return [{
  json: {
    ...data,
    generated_emails: uniquePatterns,
    email_generation_method: "pattern_based"
  }
}];

// Verify generated emails in bulk and select best
const data = $input.first().json;
const generatedEmails = data.generated_emails || [];

if (generatedEmails.length === 0) {
  return [{
    json: {
      ...data,
      email: null,
      email_verified: false,
      email_confidence: 0
    }
  }];
}

// For now, return first pattern for verification
// In production, you'd call NeverBounce bulk API
return [{
  json: {
    ...data,
    email: generatedEmails[0],
    email_source: "generated",
    email_candidates: generatedEmails
  }
}];

// Calculate contact quality score (0-100)
const data = $input.first().json;

let score = 0;

// 1. Email verification status (max 30 pts)
const emailResult = data.result || data.email_verification_result || "unknown";
if (emailResult === "valid") {
  score += 30;
} else if (emailResult === "catchall") {
  score += 15;
} else if (emailResult === "unknown" && data.email) {
  score += 10;
}

// 2. Phone number present (max 20 pts)
const phone = data.phone_numbers?.[0] || data.mobile_phone || data.phone || null;
if (phone && phone.length > 5) {
  score += 20;
}

// 3. LinkedIn URL present (max 10 pts)
if (data.linkedin_url && data.linkedin_url.includes('linkedin.com')) {
  score += 10;
}

// 4. Company size (max 10 pts)
const companySize = data.company_size || "";
if (companySize.includes('100') || companySize.includes('500') || companySize.includes('1000')) {
  score += 10;
} else if (companySize.includes('50')) {
  score += 7;
} else if (companySize.includes('10')) {
  score += 5;
}

// 5. Seniority level (max 15 pts)
const seniority = data.seniority || "unknown";
if (seniority === "executive") {
  score += 15;
} else if (seniority === "senior") {
  score += 12;
} else if (seniority === "mid") {
  score += 10;
} else if (seniority === "junior") {
  score += 7;
}

// 6. HR relevance (max 10 pts)
const hrRelevance = data.hr_relevance_score || 0;
if (hrRelevance >= 50) {
  score += 10;
} else if (hrRelevance >= 30) {
  score += 7;
} else if (hrRelevance >= 20) {
  score += 5;
}

// 7. Profile freshness (max 5 pts)
const daysSinceUpdate = data.days_since_update;
if (daysSinceUpdate !== null) {
  if (daysSinceUpdate <= 30) {
    score += 5;
  } else if (daysSinceUpdate <= 90) {
    score += 3;
  } else if (daysSinceUpdate <= 180) {
    score += 1;
  }
}

// Determine tier
const hotThreshold = $node["Validate Input"].json.hot_threshold || 80;
const warmThreshold = $node["Validate Input"].json.warm_threshold || 60;

let tier = "discard";
if (score >= hotThreshold) {
  tier = "hot";
} else if (score >= warmThreshold) {
  tier = "warm";
}

return [{
  json: {
    ...data,
    quality_score: Math.round(score),
    tier: tier,
    score_breakdown: {
      email_verification: emailResult === "valid" ? 30 : (emailResult === "catchall" ? 15 : 10),
      phone_present: phone ? 20 : 0,
      linkedin_present: data.linkedin_url ? 10 : 0,
      company_size_score: companySize ? 10 : 0,
      seniority_score: seniority === "executive" ? 15 : 0,
      hr_relevance: hrRelevance >= 50 ? 10 : 0,
      profile_freshness: daysSinceUpdate <= 30 ? 5 : 0
    },
    scoring_timestamp: new Date().toISOString()
  }
}];

// Aggregate all results from batch processing
const allResults = $input.all();

const hotLeads = allResults.filter(r => r.json.tier === "hot");
const warmLeads = allResults.filter(r => r.json.tier === "warm");
const discarded = allResults.filter(r => r.json.tier === "discard");

const config = $node["Validate Input"].json;
const startTime = new Date(config.start_time);
const endTime = new Date();
const executionTimeSeconds = Math.round((endTime - startTime) / 1000);

return [{
  json: {
    request_id: config.request_id,
    company_url: config.linkedin_company_url,
    total_processed: allResults.length,
    hot_count: hotLeads.length,
    warm_count: warmLeads.length,
    cold_count: 0, // Could separate warm/cold if needed
    discarded_count: discarded.length,
    execution_time_seconds: executionTimeSeconds,
    timestamp: new Date().toISOString(),
    hot_leads: hotLeads.slice(0, 5).map(l => l.json.full_name), // Top 5 hot leads
    status: "success"
  }
}];

